//! Replay of SciPy's recorded line searches through the `MoreThuente` ask/tell state machine.
//!
//! Validates: the port of `DCSRCH`/`dcstep` against SciPy 1.16.3
//! (`scipy/optimize/_dcsrch.py`, `_linesearch.py`, commit
//! b9105ccc2237f57acb1060202cd77f6dd264fb34). The data is generated by
//! `scripts/gen_minimize_linesearch_reference.py`: SciPy's own `test_scalar_search_wolfe1`,
//! `test_line_search_wolfe1` and `test_wolfe_terminate` problems (run = `scipy`, numpy functions),
//! the Moré–Thuente functions with the paper's (mu, eta) and the text variants, and the edge cases.
//!
//! Each recorded `(phi, phi')` pair is fed to `tell`, so no function is evaluated here. For every
//! recorded trial the requested alpha must equal SciPy's within a relative 1e-12, the number of
//! trials must be the same, and the reason must be the same.
//!
//! Tolerance policy (mathematical parity, not bitwise agreement): the replay feeds SciPy's own
//! values, so the only arithmetic that can differ is the port's (`+ - * / sqrt`, which are
//! correctly rounded on both sides); 1e-12 leaves room for a legitimately reordered expression
//! (e.g. `stp + 0.5*(sty - stx)` written another way) without hiding a different branch, which
//! moves a step by far more. Do not loosen without a written reason.
//!
//! Known, intentional difference from `_dcsrch.py`: dcstep Case 1 takes the cubic step when
//! `|stpc - stx| < |stpq - stx|` (strict), as Moré–Thuente (1994, p. 299), the MINPACK Fortran and
//! SciPy's C copy in `__lbfgsb.c` do; the Python port in `_dcsrch.py` has `<=`. The two differ only
//! on an exact tie |stpc - stx| == |stpq - stx| with stpc != stpq, so no recorded run here depends
//! on it (they all replay with either rule). Likewise the port follows MINPACK, not the paper's
//! prose ("closest"), in Case 3 (the farther step, the bound fallback and the [1.1, 4] clamp, whose
//! tables the code produced) and in the stage switch (`phi' >= 0`).
//!
//! Not replayed: the runs of group `nonfinite` (inf / NaN phi), because the maintainer's decision on
//! non-finite values is open (issue #38, review section 9.1). `termination.rs` covers them with the
//! claims every option shares.

mod common;

use common::*;
use minimize::linesearch::{MoreThuente, Step};

const STEP_TOL: f64 = 1e-12;

fn replay(case: &Case) {
    let setup = case.setup();
    let cfg = setup.config();
    let started = MoreThuente::start(&cfg, case.phi0, case.dphi0, case.alpha1);

    if case.reason.starts_with("err_") {
        let e = started
            .err()
            .unwrap_or_else(|| panic!("{}: expected StartError", case.id));
        assert_eq!(
            start_error_name(&e),
            case.reason,
            "{}: start error",
            case.id
        );
        assert_eq!(case.n_trials, 0, "{}: SciPy evaluated nothing", case.id);
        return;
    }

    let (mut ls, mut step) = started.unwrap_or_else(|e| {
        panic!(
            "{}: unexpected StartError {}",
            case.id,
            start_error_name(&e)
        )
    });
    let n = case.n_trials;
    assert!(
        n >= 1,
        "{}: a started search asks for at least one trial",
        case.id
    );
    for (k, &(alpha, phi, dphi)) in case.trials.iter().enumerate() {
        let asked = match step {
            Step::Evaluate { alpha } => alpha,
            Step::Done(t) => panic!(
                "{}: finished ({}) after {k} trials, SciPy asked for {n}",
                case.id,
                reason_name(&t.reason)
            ),
        };
        assert!(
            rel_close(asked, alpha, STEP_TOL),
            "{}: trial {k}: asked {asked:e}, SciPy {alpha:e}",
            case.id
        );
        if case.reason == "maxiter" && k == n - 1 {
            // SciPy evaluated this point but its maxiter ran out before testing it: the state
            // machine has asked for it, and that is all there is to compare.
            return;
        }
        step = ls.tell(&cfg, phi, dphi);
    }

    match step {
        Step::Done(t) => {
            assert_eq!(
                reason_name(&t.reason),
                case.reason,
                "{}: reason ({})",
                case.id,
                case.task
            );
            assert_eq!(t.evaluations, n, "{}: evaluations", case.id);
            let &(_, phi, dphi) = case.trials.last().unwrap();
            if case.reason == "converged" {
                let stp = case.stp.expect("converged runs return a step");
                assert!(
                    rel_close(t.alpha, stp, STEP_TOL),
                    "{}: alpha {:e} vs {stp:e}",
                    case.id,
                    t.alpha
                );
                assert_eq!(t.phi, phi, "{}: phi at the final step", case.id);
                assert_eq!(t.dphi, dphi, "{}: phi' at the final step", case.id);
            } else {
                // SciPy returns `None` for every warning; Termination.alpha is the port's own
                // (MINPACK: the best point), so only the reason and the count are compared.
                assert!(
                    case.stp.is_none(),
                    "{}: SciPy returns None for {}",
                    case.id,
                    case.reason
                );
            }
        }
        Step::Evaluate { alpha } => panic!(
            "{}: still asking for {alpha:e} after all {n} trials; SciPy ended with {}",
            case.id, case.reason
        ),
    }
}

#[test]
fn replays_every_recorded_run() {
    let cases = load_cases();
    assert!(
        cases.len() > 100,
        "the data set shrank: {} runs",
        cases.len()
    );
    let mut replayed = 0;
    for case in cases.iter().filter(|c| !c.is_nonfinite_group()) {
        replay(case);
        replayed += 1;
    }
    assert!(replayed > 100);
}

#[test]
fn replays_scipys_own_test_problems() {
    // 9 scalar runs (3 functions x 3 old_phi0) and 18 line runs (2 functions x 9 seeded x, p):
    // SciPy's numpy functions, not the closed forms.
    let cases: Vec<Case> = load_cases()
        .into_iter()
        .filter(|c| c.run == "scipy")
        .collect();
    assert_eq!(
        cases.iter().filter(|c| c.group == "scipy_scalar").count(),
        9
    );
    assert_eq!(cases.iter().filter(|c| c.group == "scipy_line").count(), 18);
    for case in &cases {
        replay(case);
    }
}

#[test]
fn replays_the_paper_runs() {
    // Tables I-VI (24 runs) and the five text-stated variants (20 runs); the paper's own numbers
    // are asserted in paper_tables.rs, this checks the port against SciPy on the same runs.
    let cases: Vec<Case> = load_cases()
        .into_iter()
        .filter(|c| c.group == "paper_table" || c.group == "paper_text")
        .collect();
    assert_eq!(cases.len(), 24 + 20);
    for case in &cases {
        replay(case);
    }
}

#[test]
fn replays_the_edge_cases() {
    // not descent, alpha0 above/below the bounds, monotone phi (STPMAX), maxiter = 2, finite
    // overflow in dcstep, and the searched STPMIN / XTOL / ROUNDING ERRORS runs.
    let cases: Vec<Case> = load_cases()
        .into_iter()
        .filter(|c| matches!(c.group.as_str(), "edge" | "init" | "search"))
        .collect();
    assert!(cases.len() >= 14);
    for case in &cases {
        replay(case);
    }
}
